/**
 * Audio Mapper: recorded voice-over first, TTS as the fallback
 *
 * Logic: GameHub.speak(text) hands the text to AudioMapper.speak(). If a recording exists for
 * that text (listed in Static/audio/audio-manifest.js) it is played; otherwise the TTS callback runs.
 *
 * Matching ignores case and punctuation, so "Which word fits this shape?" finds
 * "Which word fits this shape.wav" (Windows can't use "?" in file names) and KNIGHT finds knight.wav.
 * Retakes are picked up automatically: dog.wav, dog_1.wav, dog_2.wav ...
 *
 * The manifest is generated by build_audio_manifest.py (browsers cannot list a folder).
 * No manifest / no match / file fails to load  ->  the normal TTS runs, nothing breaks.
 */
(function () {
  const BASE = 'Static/audio/';        // folder that holds the audio files + audio-manifest.js
  const TAKE_MODE = 'random';          // 'random' = vary between retakes, 'first' = always the first take

  // MUST match normalize() in build_audio_manifest.py (and audio_matcher.html)
  const NUM = { 0: 'zero', 1: 'one', 2: 'two', 3: 'three', 4: 'four', 5: 'five',
                6: 'six', 7: 'seven', 8: 'eight', 9: 'nine', 10: 'ten' };
  function normalize(text) {
    return String(text == null ? '' : text).toLowerCase()
      .replace(/['’]/g, '')
      .replace(/\b(10|[0-9])\b/g, m => NUM[m])
      .replace(/[^a-z ]+/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  }

  // Looks the text up in the manifest: exact key first, then ignoring spaces
  // (so "Ahchoo" still finds "Ah choo.wav" and "didnt" finds "didn t").
  let squashIndex = null, squashFor = null;
  function findFiles(text) {
    const manifest = window.AudioManifest;
    if (!manifest) return null;
    const key = normalize(text);
    if (!key) return null;
    let files = manifest[key];
    if (!files) {
      if (squashFor !== manifest) {
        squashIndex = new Map();
        for (const k in manifest) squashIndex.set(k.replace(/ /g, ''), k);
        squashFor = manifest;
      }
      const k2 = squashIndex.get(key.replace(/ /g, ''));
      files = k2 ? manifest[k2] : null;
    }
    return files && files.length ? files : null;
  }

  const lastTake = new Map();          // remembers the last take so a retake never repeats back-to-back
  function pickFile(files) {
    if (files.length === 1 || TAKE_MODE === 'first') return files[0];
    let i;
    do { i = Math.floor(Math.random() * files.length); } while (i === lastTake.get(files[0]));
    lastTake.set(files[0], i);
    return files[i];
  }

  // One shared <audio> element: the browser lets it keep playing after the first user tap (matters on iOS)
  const player = new Audio();
  player.preload = 'auto';
  let token = 0;                       // bumped on every speak()/stop(), so a stale error/fallback can't fire late

  function stop() {
    token++;
    try { player.pause(); player.currentTime = 0; } catch (e) { /* nothing playing */ }
  }

  /**
   * @param text      what the game wants spoken
   * @param lang      language code (recordings are English only)
   * @param fallback  function that speaks the text with TTS; called when there is no usable recording
   */
  function speak(text, lang, fallback) {
    stop();
    const mine = token;
    const useFallback = () => { if (mine === token && typeof fallback === 'function') fallback(); };

    if (lang && !/^en/i.test(lang)) return useFallback();
    const files = findFiles(text);
    if (!files) return useFallback();

    if ('speechSynthesis' in window) window.speechSynthesis.cancel();   // never talk over a clip
    const file = pickFile(files);
    player.onerror = useFallback;                                       // listed but missing/corrupt -> TTS
    player.src = BASE + file.split('/').map(encodeURIComponent).join('/');
    const p = player.play();
    if (p && typeof p.catch === 'function') p.catch(useFallback);       // autoplay blocked -> TTS
  }

  window.AudioMapper = {
    speak,
    stop,
    has: text => !!findFiles(text),    // handy in the console: AudioMapper.has("dog")
    normalize
  };
})();
